<?php
namespace Tests\Feature;
use App\Models\{User,Apprentice,Programme,ProgrammeOutcome,LearningTask,CohortForecast as Forecast,CohortSnapshot as Snapshot};
use App\Support\{CohortInsights as I,CohortForecasts as F,ReviewedImports};
use Illuminate\Foundation\Testing\LazilyRefreshDatabase;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\ValidationException;
use Tests\Support\AuditFault;
use Tests\TestCase;
class CohortInsightsTest extends TestCase {
 use LazilyRefreshDatabase;
 private function f():array {$this->travelTo(today()->setTime(10,0));$admin=User::factory()->create(['role'=>'admin']);$tutor=User::factory()->create(['role'=>'tutor']);$programme=Programme::factory()->create();$a=Apprentice::factory()->create(['tutor_id'=>$tutor->id,'programme_id'=>$programme->id,'start_date'=>today()->subYear()->toDateString(),'planned_end_date'=>today()->addYear()->toDateString()]);ProgrammeOutcome::factory()->create(['apprentice_id'=>$a->id,'context'=>['status'=>'Active','sourceRef'=>'Fictional status source']]);return compact('admin','tutor','programme','a');}
 private function report(array $f,?int $programme=null,?int $tutor=null):array {return I::report($f['admin'],today()->subYears(2)->toDateString(),today()->toDateString(),$programme,$tutor);}
 private function set(array $f,array $context):void {ProgrammeOutcome::where('apprentice_id',$f['a']->id)->first()->update(['context'=>$context]);}
 private function forecast(array $f,int $version=0,string $basis='Staff estimate'):void {F::save($f['tutor'],1,$f['a']->fresh(),$version,F::source($f['a']->fresh())['hash'],today()->addDays(60)->toDateString(),today()->addDays(14)->toDateString(),$basis,'Checked staff source reference','Reviewed training estimate');}
 private function snap(array $f):Snapshot {$report=$this->report($f);return I::snapshot($f['admin'],1,today()->subYears(2)->toDateString(),today()->toDateString(),null,null,$report['source_hash']);}
 private function reject(callable $fn):void {try{$fn();$this->fail('Expected checked rejection');}catch(ValidationException $e){$this->assertNotEmpty($e->errors());}}
 public function test_current_start_cohort_keeps_known_and_unknown_status_denominators():void {$f=$this->f();Apprentice::factory()->create(['start_date'=>today()->subMonths(3)]);$r=$this->report($f)['aggregate'];$this->assertSame(2,$r['counts']['cohort']);$this->assertSame(1,$r['counts']['active']);$this->assertSame(1,$r['counts']['unknown']);$this->assertNull($r['confirmed_completion_result_percent']);$this->assertFalse($r['official_qar']);}
 public function test_missing_start_is_outside_date_cohort_and_disclosed():void {$f=$this->f();Apprentice::factory()->create(['programme_id'=>$f['programme']->id]);$r=$this->report($f)['aggregate'];$this->assertSame(1,$r['counts']['cohort']);$this->assertSame(1,$r['missing_start_outside_cohort']);}
 public function test_future_starts_are_not_in_current_start_cohort():void {$f=$this->f();Apprentice::factory()->create(['start_date'=>today()->addDay()]);$this->assertSame(1,$this->report($f)['aggregate']['counts']['cohort']);}
 #[\PHPUnit\Framework\Attributes\TestWith(['Active'])] #[\PHPUnit\Framework\Attributes\TestWith(['Completed'])] #[\PHPUnit\Framework\Attributes\TestWith(['Withdrawn'])]
 public function test_status_without_source_is_unknown(string $status):void {$f=$this->f();$this->set($f,['status'=>$status]);$c=$this->report($f)['aggregate']['counts'];$this->assertSame(1,$c['unknown']);$this->assertSame(1,$c['source_checks']);}
 public function test_future_or_pre_start_end_is_not_treated_as_valid_completion():void {$f=$this->f();foreach([today()->addDay()->toDateString(),today()->subYears(2)->toDateString()]as$date){$this->set($f,['status'=>'Completed','sourceRef'=>'Checked source','endDate'=>$date,'achievement'=>'Achieved','achievementDate'=>$date]);$this->assertSame(1,$this->report($f)['aggregate']['counts']['unknown']);}}
 public function test_achieved_requires_dated_result_on_or_after_end():void {$f=$this->f();$this->set($f,['status'=>'Completed','sourceRef'=>'Checked source','endDate'=>today()->subDays(5)->toDateString(),'achievement'=>'Achieved','achievementDate'=>today()->subDays(6)->toDateString()]);$r=$this->report($f)['aggregate'];$this->assertSame(1,$r['counts']['completed']);$this->assertSame(1,$r['counts']['result_unknown']);$this->assertNull($r['confirmed_completion_result_percent']);}
 public function test_known_completion_results_have_explicit_completion_denominator():void {$f=$this->f();$this->set($f,['status'=>'Completed','sourceRef'=>'Checked source','endDate'=>today()->subDays(5)->toDateString(),'achievement'=>'Achieved','achievementDate'=>today()->subDay()->toDateString()]);$r=$this->report($f)['aggregate'];$this->assertEquals(100,$r['confirmed_completion_result_percent']);$this->assertSame(1,$r['counts']['completed']);$this->assertFalse($r['official_qar']);}
 public function test_awaiting_or_unknown_result_withholds_percentage():void {$f=$this->f();foreach(['Awaiting result','Unknown']as$result){$this->set($f,['status'=>'Completed','sourceRef'=>'Checked source','endDate'=>today()->subDay()->toDateString(),'achievement'=>$result]);$this->assertNull($this->report($f)['aggregate']['confirmed_completion_result_percent']);}}
 public function test_break_in_learning_is_not_past_end_active_flag():void {$f=$this->f();$f['a']->update(['planned_end_date'=>today()->subDay()]);$this->set($f,['status'=>'Break in learning','sourceRef'=>'Checked break source']);$c=$this->report($f)['aggregate']['counts'];$this->assertSame(1,$c['break']);$this->assertSame(0,$c['past_recorded_end']);}
 public function test_recorded_end_unknown_is_separate_from_overdue_active():void {$f=$this->f();$f['a']->update(['planned_end_date'=>null]);$c=$this->report($f)['aggregate']['counts'];$this->assertSame(1,$c['planned_end_unknown']);$this->assertSame(0,$c['past_recorded_end']);$f['a']->update(['planned_end_date'=>today()->subDay()]);$this->assertSame(1,$this->report($f)['aggregate']['counts']['past_recorded_end']);}
 public function test_programme_version_and_current_tutor_filters_are_explicit():void {$f=$this->f();$other=Programme::factory()->create(['standard_code'=>'OTHER-43','version'=>'2']);Apprentice::factory()->create(['programme_id'=>$other->id,'start_date'=>today()->subMonths(2)]);$all=$this->report($f)['aggregate'];$this->assertCount(2,$all['groups']);$this->assertSame(1,$this->report($f,$f['programme']->id)['aggregate']['counts']['cohort']);$this->assertSame(1,$this->report($f,null,$f['tutor']->id)['aggregate']['counts']['cohort']);$this->assertFalse($all['historical_staff_attribution']);}
 public function test_source_pending_task_approval_is_not_a_known_approved_task():void {$f=$this->f();LearningTask::factory()->create(['apprentice_id'=>$f['a']->id,'status'=>'Approved','template'=>['kind'=>'source-pending']]);$c=$this->report($f)['aggregate']['counts'];$this->assertSame(1,$c['assigned_tasks']);$this->assertSame(1,$c['source_pending_tasks']);$this->assertSame(0,$c['approved_tasks']);$this->assertSame(0,$c['achieved']);}
 public function test_authorised_staff_estimate_has_current_source_review_and_no_guarantee():void {$f=$this->f();$this->forecast($f);$x=Forecast::find($f['a']->id);$this->assertTrue(F::current($x,F::source($f['a'])));$this->assertFalse($x->details['guaranteed_completion']);$this->assertSame(1,$this->report($f)['aggregate']['counts']['current_forecasts']);$this->assertSame(0,$this->report($f)['aggregate']['counts']['achieved']);}
 public function test_forecast_after_review_date_needs_new_review():void {$f=$this->f();$this->forecast($f);$this->travel(15)->days();$this->assertFalse(F::current(Forecast::find($f['a']->id),F::source($f['a'])));}
 public function test_task_or_assignment_change_holds_forecast_and_old_tutor_access():void {$f=$this->f();$this->forecast($f);LearningTask::factory()->create(['apprentice_id'=>$f['a']->id]);$this->assertFalse(F::current(Forecast::find($f['a']->id),F::source($f['a'])));$other=User::factory()->create(['role'=>'tutor']);$f['a']->update(['tutor_id'=>$other->id]);$this->actingAs($f['tutor'])->get('/apprentices/'.$f['a']->id.'/checked-estimate')->assertForbidden();}
 public function test_closed_programme_and_unknown_status_cannot_receive_current_estimate():void {$f=$this->f();foreach(['Completed','Withdrawn','Unknown']as$status){$this->set($f,['status'=>$status,'sourceRef'=>'Checked source']);$this->reject(fn()=>$this->forecast($f));}}
 public function test_approved_plan_basis_without_current_approval_rejected():void {$f=$this->f();$this->reject(fn()=>$this->forecast($f,0,'Approved plan reference'));}
 public function test_estimate_review_cannot_follow_target_date():void {$f=$this->f();$this->reject(fn()=>F::save($f['tutor'],1,$f['a'],0,F::source($f['a'])['hash'],today()->addDay()->toDateString(),today()->addDays(2)->toDateString(),'Staff estimate','Checked source','Checked reason'));}
 public function test_stale_forecast_version_and_source_are_held():void {$f=$this->f();$hash=F::source($f['a'])['hash'];$this->forecast($f);$this->reject(fn()=>$this->forecast($f));$f['a']->increment('version');$this->reject(fn()=>F::save($f['tutor'],1,$f['a']->fresh(),1,$hash,today()->addMonth()->toDateString(),today()->addDay()->toDateString(),'Staff estimate','Checked source','Checked reason'));}
 public function test_revised_estimate_is_encrypted_and_retains_prior_reference():void {$f=$this->f();$this->forecast($f);$this->forecast($f,1);$x=Forecast::find($f['a']->id);$this->assertCount(1,$x->details['history']);$this->assertStringNotContainsString('Checked staff source',DB::table('cohort_forecasts')->value('details'));}
 public function test_snapshot_exports_aggregate_without_learner_identity_or_source_reference():void {$f=$this->f();$f['a']->update(['first_name'=>'PRIVATE-FIRSTNAME-43','reference'=>'PRIVATE-REFERENCE-43']);$this->set($f,['status'=>'Active','sourceRef'=>'PRIVATE-SOURCE-REFERENCE-43','ehcp'=>'Yes','additional'=>'Yes','reason'=>'PRIVATE-CONTEXT-43']);$s=$this->snap($f);$text=json_encode(I::readSnapshot($s));foreach(['PRIVATE-FIRSTNAME','PRIVATE-REFERENCE','PRIVATE-SOURCE','PRIVATE-CONTEXT','ehcp','additional']as$secret){$this->assertStringNotContainsString($secret,$text);}$this->assertStringNotContainsString('cohort_definition',DB::table('cohort_snapshots')->value('body'));}
 public function test_snapshot_is_immutable_after_live_outcome_changes():void {$f=$this->f();$s=$this->snap($f);$old=I::readSnapshot($s);$this->set($f,['status'=>'Completed','sourceRef'=>'Checked source','endDate'=>today()->subDay()->toDateString(),'achievement'=>'Not achieved']);$this->assertSame($old,I::readSnapshot($s->fresh()));$this->assertSame(1,$this->report($f)['aggregate']['counts']['completed']);}
 public function test_snapshot_preview_source_change_requires_recheck():void {$f=$this->f();$hash=$this->report($f)['source_hash'];$this->set($f,['status'=>'Break in learning','sourceRef'=>'Checked source']);$this->reject(fn()=>I::snapshot($f['admin'],1,today()->subYears(2)->toDateString(),today()->toDateString(),null,null,$hash));$this->assertDatabaseCount('cohort_snapshots',0);}
 public function test_same_cohort_snapshots_compare_captured_differences():void {$f=$this->f();$a=$this->snap($f);$this->travel(1)->hours();$this->set($f,['status'=>'Completed','sourceRef'=>'Checked source','endDate'=>today()->subDay()->toDateString(),'achievement'=>'Not achieved']);$b=$this->snap($f);$cmp=I::compare($a,$b);$this->assertSame(1,$cmp['changes']['completed']);$this->assertSame(-1,$cmp['changes']['active']);}
 public function test_snapshot_comparison_requires_same_cohort_filters_and_chronology():void {$f=$this->f();$a=$this->snap($f);$this->travel(1)->hours();$b=$this->snap($f);$this->reject(fn()=>I::compare($b,$a));$body=$b->body;$body['report']['from']=today()->subYear()->toDateString();$b->body=$body;$b->body_hash=ReviewedImports::hash($body);$b->save();$this->reject(fn()=>I::compare($a,$b));}
 public function test_tampered_snapshot_never_substitutes_live_data():void {$f=$this->f();$s=$this->snap($f);DB::table('cohort_snapshots')->where('id',$s->id)->update(['body_hash'=>str_repeat('0',64)]);$this->reject(fn()=>I::readSnapshot($s->fresh()));}
 public function test_snapshot_audit_failure_rolls_back_capture():void {$f=$this->f();AuditFault::install('snapshot_fault','portal_operations_events','Fictional failure','cohort_snapshot_saved');try{$this->snap($f);$this->fail('Expected failure');}catch(\Illuminate\Database\QueryException){$this->assertDatabaseCount('cohort_snapshots',0);}}
 public function test_forecast_audit_failure_rolls_back_estimate():void {$f=$this->f();AuditFault::install('forecast_fault','portal_operations_events','Fictional failure','forecast_recorded');try{$this->forecast($f);$this->fail('Expected failure');}catch(\Illuminate\Database\QueryException){$this->assertDatabaseCount('cohort_forecasts',0);}}
 #[\PHPUnit\Framework\Attributes\TestWith(['tutor'])] #[\PHPUnit\Framework\Attributes\TestWith(['manager'])] #[\PHPUnit\Framework\Attributes\TestWith(['employer'])] #[\PHPUnit\Framework\Attributes\TestWith(['apprentice'])]
 public function test_report_and_snapshot_require_canonical_manager(string $role):void {$f=$this->f();$u=User::factory()->create(['role'=>$role]);$this->actingAs($u)->get('/reports/cohort-context')->assertForbidden();$this->post('/reports/cohort-context/snapshots',[])->assertForbidden();}
 #[\PHPUnit\Framework\Attributes\TestWith(['manager'])] #[\PHPUnit\Framework\Attributes\TestWith(['employer'])] #[\PHPUnit\Framework\Attributes\TestWith(['apprentice'])]
 public function test_unrelated_roles_cannot_write_estimate(string $role):void {$f=$this->f();$u=User::factory()->create(['role'=>$role]);$this->actingAs($u)->get('/apprentices/'.$f['a']->id.'/checked-estimate')->assertForbidden();$this->post('/apprentices/'.$f['a']->id.'/checked-estimate',[])->assertForbidden();}
 public function test_report_rejects_historical_as_of_and_overlong_dates():void {$f=$this->f();$this->actingAs($f['admin'])->get('/reports/cohort-context?as_of=2025-01-01')->assertSessionHasErrors('as_of');$this->get('/reports/cohort-context?from=2000-01-01&to='.today()->toDateString())->assertStatus(422);}
 public function test_stages_distinguish_missing_overlap_and_verified_current_block():void {$today=today()->toDateString();$this->assertSame('Approved plan missing',I::stage(null));$this->assertSame('Block 1',I::stage(['blocks'=>[['number'=>1,'start'=>$today,'end'=>$today]]]));$this->assertSame('Overlapping plan blocks',I::stage(['blocks'=>[['number'=>1,'start'=>$today,'end'=>$today],['number'=>2,'start'=>$today,'end'=>$today]]]));$this->assertSame('Plan dates need checking',I::stage(['blocks'=>[['number'=>1,'start'=>null,'end'=>$today]]]));}
 public function test_new_views_download_and_estimate_render_private_headers():void {$f=$this->f();$s=$this->snap($f);$this->actingAs($f['admin'])->get('/reports/cohort-context')->assertOk()->assertSee('What the figures include')->assertHeader('Referrer-Policy','no-referrer');$this->get('/cohort-snapshots/'.$s->id)->assertOk();$this->get('/cohort-snapshots/'.$s->id.'/aggregate.json')->assertOk()->assertHeader('Cache-Control','no-store, private');$this->actingAs($f['tutor'])->get('/apprentices/'.$f['a']->id.'/checked-estimate')->assertOk();}
}
